name: comment release fixes
on:
  {
    release: { types: [published] },
    workflow_dispatch:
      {
        inputs:
          {
            tag: { required: true, type: string },
            dry_run: { required: false, type: boolean, default: true },
          },
      },
  }
concurrency:
  group: comment-release-fixes-caller-${{ github.event.release.tag_name || inputs.tag }}
  cancel-in-progress: false
  # Every dispatch for a tag must run: without a queue a later pending dry run
  # would replace a pending live one, and the comments would never be posted.
  queue: max
jobs:
  comment:
    permissions:
      { contents: read, pull-requests: read, issues: write, discussions: write }
    uses: jdx/workflows/.github/workflows/comment-release-fixes.yml@4c952564543dd54d60f15ef4062af7fb60c5561d # v1.1.0
    with:
      {
        tag: "${{ inputs.tag || github.event.release.tag_name }}",
        marker_prefix: mr-boxington-fixed-in,
        dry_run: "${{ inputs.dry_run || false }}",
      }

