edition = "2024"
rust-version = "1.91"
version = "5.0.0"
include = [
    "/Cargo.toml",
    "/Cargo.lock",
    "/README.md",
    "/NOTICE.md",
    "/src/**/*.rs",
]
description = "Library for working with usage specs"
homepage = { workspace = true }
documentation = { workspace = true }
repository = { workspace = true }
authors = { workspace = true }
license = { workspace = true }

[dependencies]
clap = { version = "4", default-features = false, features = ["env", "std"] }
usage-lib = { workspace = true, features = ["clap"] }

[dev-dependencies]
insta = "1"

b23.text:
name: comment release fixes
on:
  {
    release: { types: [published] },
    workflow_dispatch:
      {
        inputs:
          {
            tag: { required: true, type: string },
            dry_run: { required: false, type: boolean, default: true },
          },
      },
  }
concurrency:
  group: ${{ github.workflow }}-${{ inputs.tag || github.event.release.tag_name }}
  cancel-in-progress: false
jobs:
  comment:
    permissions:
      { contents: read, pull-requests: read, issues: write, discussions: write }
    uses: jdx/workflows/.github/workflows/comment-release-fixes.yml@7e4ea6cf326e2b3bb4335f733381af531aaa699d # v1.2.1
    with:
      {
        tag: "${{ inputs.tag || github.event.release.tag_name }}",
        marker_prefix: usage-fixed-in,
        dry_run: "${{ inputs.dry_run || false }}",
      }

