[package]
name = "usage-dynamic"
description = "Runtime command catalogs for usage-rs applications"
version = "7.1.1"
edition = "2024"
rust-version = "1.91"
homepage = { workspace = true }
documentation = { workspace = true }
repository = { workspace = true }
authors = { workspace = true }
license = { workspace = true }

[dependencies]
usage-argv = { workspace = true, features = ["help-advanced", "spec", "complete"] }
usage-parser = { package = "usage-lib", path = "../lib", version = "7.1.1", default-features = false, features = ["cli-help"] }

[package.metadata.release]
shared-version = true
release = true

[dev-dependencies]
futures = "0.3"
usage-rs = { workspace = true, features = ["completions"] }

b29.text:
# The gate: the same command line, parsed by the shadow and by clap, measured with
# instruction counts. Two binaries rather than one benchmark harness, because the cost
# being compared includes what happens before `main` gets a parser — clap builds its
# command tree at runtime, and a harness that built it once outside the loop would
# measure the half of clap that is already fast.
[package]
name = "gate"
version = "0.0.0"
edition = "2024"
publish = false

[dependencies]
clap = { version = "4", features = ["derive", "env"] }
shadow-mise = { path = "../shadows/mise" }
shadow-mise-clap = { path = "../shadows/mise-clap" }
shadow-mise-bpaf = { path = "../shadows/mise-bpaf" }
bpaf = { version = "0.9", features = ["derive"] }
usage-argv = { path = "../../argv", features = ["spec", "complete", "diagnostics"] }

# The oracle for help rendering. A dev-dependency because nothing the gate *builds* needs it:
# it is here so the shadow's rendered help can be compared against usage-lib's over mise's
# whole spec, which is the only fixture big enough to be convincing.
[dev-dependencies]
usage-lib = { path = "../../lib" }
# The fleet, for the same reason: only `tests/fleet.rs` names these, so a release or perf build
# of the gate has no cause to compile six generated crates it never calls. `shadow-mise` and
# `shadow-mise-clap` stay above because the benchmarks *are* the thing that runs them.
shadow-hk = { path = "../shadows/hk" }
shadow-fnox = { path = "../shadows/fnox" }
shadow-pitchfork = { path = "../shadows/pitchfork" }
shadow-aube = { path = "../shadows/aube" }
shadow-tak = { path = "../shadows/tak" }
shadow-communique = { path = "../shadows/communique" }
shadow-fd = { path = "../shadows/external-fd" }
# The oracle for completions, for the same reason: the reference's candidate list is what
# "the same candidates" is measured against.
usage-cli = { path = "../../cli" }
proptest = "1.11.0"

b31.text:
[package]
name = "usage-conformance"
description = "Harness for the argv conformance corpus"
publish = false
version = "0.0.0"
edition = "2024"
# No `rust-version`: nobody can depend on this, so it has nobody to promise. It declared 1.91
# while depending on `usage-lib`, which needed 1.95 — a floor that was never reachable
# and that no job checked, because the matrix only covers what is published.
homepage = { workspace = true }
documentation = { workspace = true }
repository = { workspace = true }
authors = { workspace = true }
license = { workspace = true }

[dependencies]
serde = { version = "1", features = ["derive"] }
serde_json = "1"
usage-argv = { workspace = true, features = ["help-advanced", "spec", "complete", "diagnostics"] }
usage-config = { workspace = true }
usage-cli = { workspace = true }
# Both named explicitly: the corpus carries `validate=` vectors, checked against usage-lib's
# reference parser, and the suites compare rendered help against `usage::docs`.
usage-lib = { workspace = true, features = ["docs", "validation"] }

[dev-dependencies]
clap = { version = "4", features = ["derive", "env"] }
clap_usage = { workspace = true }
insta = "1"
usage-derive = { workspace = true }
# The derives write their paths through this facade; the suites still import the pieces directly.
usage-rs = { workspace = true, features = ["config", "validation", "completions", "response-files"] }
usage-validation = { workspace = true }

[[bin]]
name = "oracle"
path = "src/bin/oracle.rs"

[[bin]]
name = "render-oracle"
path = "src/bin/render-oracle.rs"

